head.b:skin:
/*
-----------------------------------------------
Name: The Bukit Besi
Version: 2.0.0-separation
Purpose: Clean, lightweight Blogger editorial template for thebukitbesi.com
----------------------------------------------- */
:root{
  --tbb-red:#b91c1c;
  --tbb-red-dark:#991b1b;
  --tbb-ink:#18181b;
  --tbb-text:#3f3f46;
  --tbb-muted:#71717a;
  --tbb-border:#e4e4e7;
  --tbb-soft:#f7f7f8;
  --tbb-bg:#ffffff;
  --tbb-card:#ffffff;
  --tbb-radius:14px;
  --tbb-shadow:0 8px 28px rgba(24,24,27,.07);
  --tbb-header:64px;
  --tbb-max:1240px;
  --tbb-font:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--tbb-bg);color:var(--tbb-text);font-family:var(--tbb-font);font-size:16px;line-height:1.7;text-rendering:optimizeLegibility}
a{color:inherit;text-decoration:none}
a:hover{color:var(--tbb-red)}
img{max-width:100%;height:auto;display:block}
button,input{font:inherit}
button{cursor:pointer}
svg{display:block}
.tbb-container{width:min(var(--tbb-max),calc(100% - 40px));margin-inline:auto}
.tbb-sr-only{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.tbb-skip{position:fixed;left:12px;top:-60px;z-index:9999;padding:10px 14px;background:#fff;color:#111;border:2px solid var(--tbb-red);border-radius:8px}
.tbb-skip:focus{top:12px}

/* Header */
.tbb-header{position:sticky;top:0;z-index:1000;height:var(--tbb-header);background:rgba(255,255,255,.96);border-bottom:1px solid var(--tbb-border);backdrop-filter:saturate(160%) blur(10px)}
.tbb-header-row{height:var(--tbb-header);display:flex;align-items:center;gap:24px}
.tbb-brand{display:inline-flex;align-items:center;gap:10px;flex:0 0 auto;color:var(--tbb-ink);font-weight:800;letter-spacing:-.025em;line-height:1}
.tbb-brand:hover{color:var(--tbb-ink)}
.tbb-brand-mark{width:11px;height:30px;background:var(--tbb-red);border-radius:3px}
.tbb-brand-text{font-size:18px;white-space:nowrap}
.tbb-nav{display:flex;align-items:center;gap:2px;margin-left:auto}
.tbb-nav a{display:flex;align-items:center;min-height:44px;padding:0 12px;border-radius:9px;color:var(--tbb-ink);font-size:14px;font-weight:650}
.tbb-nav a:hover{background:var(--tbb-soft);color:var(--tbb-red)}
.tbb-actions{display:flex;align-items:center;gap:4px}
.tbb-icon-btn{width:44px;height:44px;display:grid;place-items:center;border:0;background:transparent;color:var(--tbb-ink);border-radius:10px}
.tbb-icon-btn:hover{background:var(--tbb-soft);color:var(--tbb-red)}
.tbb-menu-btn{display:none}

/* Search */
.tbb-search-panel{display:none;position:fixed;inset:var(--tbb-header) 0 auto;z-index:999;background:var(--tbb-bg);border-bottom:1px solid var(--tbb-border);box-shadow:var(--tbb-shadow);padding:22px 0}
.tbb-search-panel.is-open{display:block}
.tbb-search-form{display:flex;gap:10px;max-width:760px;margin:auto}
.tbb-search-input{flex:1;min-width:0;height:50px;border:1px solid var(--tbb-border);border-radius:11px;padding:0 16px;background:var(--tbb-card);color:var(--tbb-ink);outline:none}
.tbb-search-input:focus{border-color:var(--tbb-red);box-shadow:0 0 0 3px rgba(185,28,28,.1)}
.tbb-search-submit{height:50px;border:0;border-radius:11px;padding:0 20px;background:var(--tbb-red);color:#fff;font-weight:750}
.tbb-search-submit:hover{background:var(--tbb-red-dark)}

/* Home hero */
.tbb-hero{padding:56px 0 34px;background:linear-gradient(180deg,#fff 0%,#fafafa 100%);border-bottom:1px solid var(--tbb-border)}
.tbb-hero-inner{max-width:820px}
.tbb-kicker{display:inline-flex;align-items:center;gap:8px;margin-bottom:14px;color:var(--tbb-red);font-size:13px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}
.tbb-kicker:before{content:"";width:22px;height:3px;background:var(--tbb-red);border-radius:4px}
.tbb-hero h1{margin:0;color:var(--tbb-ink);font-size:clamp(34px,5vw,60px);line-height:1.04;letter-spacing:-.045em}
.tbb-hero p{max-width:680px;margin:18px 0 0;font-size:18px;color:var(--tbb-muted)}
.tbb-quick{display:flex;flex-wrap:wrap;gap:8px;margin-top:24px}
.tbb-quick a{padding:8px 12px;border:1px solid var(--tbb-border);background:#fff;border-radius:999px;font-size:13px;font-weight:650;color:var(--tbb-ink)}
.tbb-quick a:hover{border-color:var(--tbb-red);color:var(--tbb-red)}

/* Main */
.tbb-main{padding:36px 0 56px}
.tbb-layout{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:36px;align-items:start}
.tbb-content{min-width:0}
.tbb-section-head{display:flex;align-items:end;justify-content:space-between;gap:20px;margin-bottom:20px}
.tbb-section-head h2{margin:0;color:var(--tbb-ink);font-size:25px;line-height:1.2;letter-spacing:-.025em}
.tbb-section-head p{margin:4px 0 0;color:var(--tbb-muted);font-size:14px}

/* Cards */
.tbb-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}
.tbb-card{min-width:0;border:1px solid var(--tbb-border);border-radius:var(--tbb-radius);overflow:hidden;background:var(--tbb-card);transition:transform .18s ease,border-color .18s ease,box-shadow .18s ease}
.tbb-card:hover{transform:translateY(-2px);border-color:#d4d4d8;box-shadow:var(--tbb-shadow)}
.tbb-card-media{position:relative;aspect-ratio:16/9;overflow:hidden;background:#f1f1f2}
.tbb-card-media img{width:100%;height:100%;object-fit:cover;transition:transform .25s ease}
.tbb-card:hover .tbb-card-media img{transform:scale(1.02)}
.tbb-card-body{padding:17px 18px 18px}
.tbb-labels{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:9px}
.tbb-label{font-size:11px;line-height:1.2;font-weight:800;text-transform:uppercase;letter-spacing:.055em;color:var(--tbb-red)}
.tbb-card h2,.tbb-card h3{margin:0;color:var(--tbb-ink);font-size:20px;line-height:1.28;letter-spacing:-.025em}
.tbb-card h2 a:hover,.tbb-card h3 a:hover{color:var(--tbb-red)}
.tbb-meta{display:flex;flex-wrap:wrap;gap:8px 12px;margin-top:11px;color:var(--tbb-muted);font-size:12px}
.tbb-snippet{margin:11px 0 0;color:var(--tbb-text);font-size:14px;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:3;overflow:hidden}
.tbb-empty{padding:34px;border:1px dashed var(--tbb-border);border-radius:var(--tbb-radius);text-align:center;color:var(--tbb-muted)}

/* Sidebar */
.tbb-sidebar{display:grid;gap:18px;position:sticky;top:calc(var(--tbb-header) + 20px)}
.tbb-side-card{border:1px solid var(--tbb-border);border-radius:var(--tbb-radius);padding:20px;background:var(--tbb-card)}
.tbb-side-card h2{margin:0 0 12px;color:var(--tbb-ink);font-size:16px;letter-spacing:-.01em}
.tbb-side-links{display:grid;gap:3px}
.tbb-side-links a{padding:9px 10px;margin:0 -10px;border-radius:8px;font-size:14px;font-weight:600;color:var(--tbb-text)}
.tbb-side-links a:hover{background:var(--tbb-soft);color:var(--tbb-red)}
.tbb-about{font-size:14px;color:var(--tbb-muted);margin:0}

/* Pagination */
.tbb-pagination{display:flex;justify-content:space-between;gap:12px;margin-top:30px}
.tbb-page-btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0 16px;border:1px solid var(--tbb-border);border-radius:10px;background:#fff;color:var(--tbb-ink);font-size:14px;font-weight:700}
.tbb-page-btn:hover{border-color:var(--tbb-red);color:var(--tbb-red)}

/* Post */
.tbb-post{max-width:860px;margin-inline:auto}
.tbb-breadcrumb{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-bottom:18px;color:var(--tbb-muted);font-size:13px}
.tbb-breadcrumb a:hover{color:var(--tbb-red)}
.tbb-post-header{margin-bottom:24px}
.tbb-post-header h1{margin:0;color:var(--tbb-ink);font-size:clamp(34px,5vw,54px);line-height:1.08;letter-spacing:-.04em}
.tbb-post-lead{margin-top:14px;color:var(--tbb-muted);font-size:18px}
.tbb-post-meta{display:flex;flex-wrap:wrap;gap:8px 14px;margin-top:16px;color:var(--tbb-muted);font-size:13px}
.tbb-post-cover{margin:26px 0 30px;border-radius:16px;overflow:hidden;background:#f4f4f5;aspect-ratio:16/9}
.tbb-post-cover img{width:100%;height:100%;object-fit:cover}
.tbb-post-body{color:var(--tbb-text);font-size:17px;line-height:1.82;overflow-wrap:anywhere}
.tbb-post-body>p:first-child{margin-top:0}
.tbb-post-body h2{margin:2em 0 .7em;color:var(--tbb-ink);font-size:30px;line-height:1.2;letter-spacing:-.025em}
.tbb-post-body h3{margin:1.7em 0 .6em;color:var(--tbb-ink);font-size:23px;line-height:1.25}
.tbb-post-body h4{margin:1.5em 0 .5em;color:var(--tbb-ink);font-size:19px}
.tbb-post-body a{color:var(--tbb-red);text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:3px}
.tbb-post-body img{margin:24px auto;border-radius:12px}
.tbb-post-body figure{margin:28px 0}
.tbb-post-body figcaption{margin-top:8px;text-align:center;color:var(--tbb-muted);font-size:13px}
.tbb-post-body blockquote{margin:26px 0;padding:2px 0 2px 20px;border-left:4px solid var(--tbb-red);color:#52525b;font-size:18px}
.tbb-post-body table{width:100%;border-collapse:collapse;margin:24px 0;font-size:15px;display:block;overflow-x:auto}
.tbb-post-body th,.tbb-post-body td{padding:10px 12px;border:1px solid var(--tbb-border);text-align:left;vertical-align:top}
.tbb-post-body th{background:var(--tbb-soft);color:var(--tbb-ink)}
.tbb-post-body pre{overflow:auto;padding:16px;border-radius:10px;background:#18181b;color:#f4f4f5;font-size:14px}
.tbb-post-body code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}
.tbb-share{display:flex;flex-wrap:wrap;gap:8px;padding:22px 0;margin-top:28px;border-top:1px solid var(--tbb-border);border-bottom:1px solid var(--tbb-border)}
.tbb-share button{min-height:42px;padding:0 14px;border:1px solid var(--tbb-border);border-radius:9px;background:#fff;color:var(--tbb-ink);font-weight:700;font-size:13px}
.tbb-share button:hover{border-color:var(--tbb-red);color:var(--tbb-red)}

/* Static/Search */
.tbb-page-title{margin:0 0 24px;color:var(--tbb-ink);font-size:34px;line-height:1.15;letter-spacing:-.035em}

/* Footer */
.tbb-footer{border-top:1px solid var(--tbb-border);background:#18181b;color:#d4d4d8;padding:40px 0 22px}
.tbb-footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:34px}
.tbb-footer-brand{color:#fff;font-size:18px;font-weight:800}
.tbb-footer p{margin:10px 0 0;color:#a1a1aa;font-size:14px;max-width:520px}
.tbb-footer h2{margin:0 0 10px;color:#fff;font-size:14px}
.tbb-footer-links{display:grid;gap:6px}
.tbb-footer-links a{font-size:14px;color:#d4d4d8}
.tbb-footer-links a:hover{color:#fff}
.tbb-copyright{margin-top:30px;padding-top:18px;border-top:1px solid #3f3f46;color:#a1a1aa;font-size:12px}

/* Dark */
html.tbb-dark{
  --tbb-ink:#fafafa;
  --tbb-text:#d4d4d8;
  --tbb-muted:#a1a1aa;
  --tbb-border:#3f3f46;
  --tbb-soft:#27272a;
  --tbb-bg:#18181b;
  --tbb-card:#202023;
  --tbb-shadow:0 8px 28px rgba(0,0,0,.22)
}
html.tbb-dark .tbb-header{background:rgba(24,24,27,.96)}
html.tbb-dark .tbb-hero{background:linear-gradient(180deg,#18181b 0%,#1f1f22 100%)}
html.tbb-dark .tbb-search-submit{color:#fff}
html.tbb-dark .tbb-quick a,html.tbb-dark .tbb-page-btn,html.tbb-dark .tbb-share button{background:var(--tbb-card)}
html.tbb-dark .tbb-post-body blockquote{color:#d4d4d8}

/* Responsive */
@media (max-width:1024px){
  .tbb-layout{grid-template-columns:minmax(0,1fr)}
  .tbb-sidebar{position:static;grid-template-columns:repeat(2,minmax(0,1fr))}
  .tbb-nav{display:none;position:fixed;top:var(--tbb-header);left:0;right:0;padding:10px 20px 16px;background:var(--tbb-bg);border-bottom:1px solid var(--tbb-border);box-shadow:var(--tbb-shadow);flex-direction:column;align-items:stretch;gap:2px}
  .tbb-nav.is-open{display:flex}
  .tbb-nav a{padding:0 12px}
  .tbb-actions{margin-left:auto}
  .tbb-menu-btn{display:grid}
}
@media (max-width:720px){
  :root{--tbb-header:58px}
  .tbb-container{width:min(100% - 28px,var(--tbb-max))}
  .tbb-header-row{gap:10px}
  .tbb-brand-mark{height:26px}
  .tbb-brand-text{font-size:16px}
  .tbb-icon-btn{width:42px;height:42px}
  .tbb-hero{padding:38px 0 28px}
  .tbb-hero p{font-size:16px}
  .tbb-main{padding:26px 0 42px}
  .tbb-grid{grid-template-columns:1fr;gap:16px}
  .tbb-card h2,.tbb-card h3{font-size:19px}
  .tbb-sidebar{grid-template-columns:1fr}
  .tbb-search-form{flex-direction:column}
  .tbb-search-submit{width:100%}
  .tbb-post-header h1{font-size:clamp(31px,10vw,42px)}
  .tbb-post-body{font-size:16.5px}
  .tbb-post-body h2{font-size:26px}
  .tbb-footer-grid{grid-template-columns:1fr}
}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}

body.script:
(function(){
  'use strict';
  var root=document.documentElement;
  var menuBtn=document.getElementById('menu-toggle');
  var nav=document.getElementById('primary-nav');
  var searchBtn=document.getElementById('search-toggle');
  var searchPanel=document.getElementById('tbb-search');
  var searchInput=document.getElementById('tbb-search-input');
  var themeBtn=document.getElementById('theme-toggle');
  var year=document.getElementById('tbb-year');
  if(year)year.textContent=new Date().getFullYear();

  function setExpanded(el,value){if(el)el.setAttribute('aria-expanded',value?'true':'false');}
  if(menuBtn&&nav){
    menuBtn.addEventListener('click',function(){
      var open=nav.classList.toggle('is-open');
      setExpanded(menuBtn,open);
    });
  }
  if(searchBtn&&searchPanel){
    searchBtn.addEventListener('click',function(){
      var open=searchPanel.classList.toggle('is-open');
      searchPanel.setAttribute('aria-hidden',open?'false':'true');
      setExpanded(searchBtn,open);
      if(open&&searchInput)window.setTimeout(function(){searchInput.focus();},0);
    });
  }
  if(themeBtn){
    themeBtn.addEventListener('click',function(){
      var dark=root.classList.toggle('tbb-dark');
      try{localStorage.setItem('tbb-theme',dark?'dark':'light');}catch(e){}
    });
  }
  document.addEventListener('keydown',function(e){
    if(e.key==='Escape'){
      if(nav)nav.classList.remove('is-open');
      if(searchPanel){searchPanel.classList.remove('is-open');searchPanel.setAttribute('aria-hidden','true');}
      setExpanded(menuBtn,false);setExpanded(searchBtn,false);
    }
  });

  var nativeShare=document.querySelector('.tbb-share-native');
  var copyShare=document.querySelector('.tbb-share-copy');
  if(nativeShare){
    nativeShare.addEventListener('click',function(){
      if(navigator.share){navigator.share({title:document.title,url:location.href}).catch(function(){});}
      else if(copyShare){copyShare.click();}
    });
  }
  if(copyShare){
    copyShare.addEventListener('click',function(){
      var button=this;
      var done=function(){var old=button.textContent;button.textContent='Pautan disalin';window.setTimeout(function(){button.textContent=old;},1600);};
      if(navigator.clipboard&&window.isSecureContext){navigator.clipboard.writeText(location.href).then(done).catch(function(){});}
    });
  }
})();
